learn=[('Deliver real tool audit events', 'PostToolUse sends actual tool metadata as JSON to a per-run loopback HTTP receiver. Inspect the request body, response status and tool-use identifier. The local receiver is a classroom integration endpoint.'), ('Handle HTTP failures and cancellation', 'Check response.ok because fetch does not throw for HTTP 503. Catch errors inside the integration callback. Pass AbortSignal to fetch and distinguish a short request deadline from an SDK hook timeout.'), ('Run tracked background work', 'Return async output for logging-only side effects. Track and drain the actual background promise before collecting final evidence. The callback can return before delivery finishes; async hooks cannot retroactively block or modify execution.'), ('Forward actual notifications', 'Keep a real Read review pending long enough for the SDK permission_prompt notification. Forward its actual message in a Slack-format text payload to the local receiver, then approve explicitly in the browser.'), ('Compare event-specific timeouts', 'A one-second PreToolUse timeout blocks the read in the verified runtime. A one-second PostToolUse timeout keeps the successful tool result. Inspect actual abort signals and native SDK feedback.'), ('Troubleshoot and track responsibly', 'Compare a file-name matcher that never fires with the correct Read matcher. Study the source-linked SubagentStop tracker as a reference. The app launches no subagents and makes no external Slack delivery.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3134\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and a supported model. Windows may require Git Bash. Python is needed only to regenerate student pages. No Slack token or external request-bin account is required.', 'node --version\nnpm --version'), ('Install and create your .env file', 'From presentations enter the application, install locked dependencies, preserve an existing .env and enter your model key privately.', 'cd .\\agent-sdk\\lesson34-hooks-practice\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open and visit port 3134. Use the five buttons for the lab, concepts, setup, UML and coloured code walkthrough. Each run starts and closes its own loopback receiver.', 'npm start\n# http://127.0.0.1:3134'), ('Compare delivery and background work', 'Run successful delivery, HTTP 503, request cancellation and async logging. Inspect the real receiver receipts and elapsed-time records. Async mode drains its tracked background work before publishing final evidence.', 'npm run sample:env -- audit-success\nnpm run sample:env -- audit-error\nnpm run sample:env -- audit-abort\nnpm run sample:env -- async-audit'), ('Observe a real permission notification', 'Choose Notification and leave the actual Read review pending for about nine seconds. Inspect the Notification callback and local Slack-format POST, then approve the Read. The CLI flag below explicitly scripts the same delayed approval for a demonstration.', 'npm run sample:env -- notification --approve-review'), ('Force timeouts and repair a matcher', 'Compare one-second pre-tool and post-tool hook timeouts. Then compare lesson.txt as a matcher with the correct Read tool-name matcher. Read the actual native feedback and delivery records.', 'npm run sample:env -- timeout-pre\nnpm run sample:env -- timeout-post\nnpm run sample:env -- matcher-miss\nnpm run sample:env -- matcher-fixed\nnpm test')]
specs=[('Validate the fixed classroom experiment', 'src/modes.ts', 'export function validateConfig', 'Accept a listed mode and bounded prediction. Browser input cannot supply a webhook URL, arbitrary tool or hook code.', 0, 1, 7), ('Start a per-run local receiver', 'src/collector.ts', 'server.listen(0,', 'Bind to a random available loopback port. The receiver records actual requests and responses; it is separate from any external Slack workspace.', 1, 4, 6), ('Bound the actual Read request', 'src/hooks.ts', 'const guard: HookCallback', 'Only lesson.txt can be read. The notification experiment returns ask so an actual pending review can generate permission_prompt.', 3, 2, 10), ('Register the selected matcher and timeout', 'src/hooks.ts', 'matcher: mode === "matcher-miss"', 'The intentionally wrong file-name matcher misses Read. The corrected matcher selects the tool name. Timeout is configured in seconds on the matcher entry.', 1, 3, 8), ('Start the real SDK query', 'src/agent.ts', 'const active = query', 'The SDK owns model and tool orchestration. Hook callbacks and native results are actual observations, not browser simulations.', 1, 2, 3), ('Capture actual callback data', 'src/hooks.ts', 'const output = await callback', 'Record the event, input, output, tool-use ID and abort state. Notification metadata is preserved separately from tool input.', 2, 3, 10), ('Send JSON and pass the AbortSignal', 'src/integrations.ts', 'const response = await fetch', 'Post bounded JSON with Content-Type and AbortSignal. A successful fetch promise alone does not imply a successful HTTP status.', 3, 4, 8), ('Catch reporting failures inside the hook', 'src/integrations.ts', 'if (!response.ok)', 'Check HTTP status, catch transport or cancellation errors and record them without rethrowing. Reporting failures must not erase an already successful tool result.', 4, 3, 9), ('Return async output and track the task', 'src/hooks.ts', 'const work = deliver', 'Start the actual delivery, retain its promise and return async output. Background-only work cannot retroactively block or modify the tool.', 3, 2, 12), ('Forward the actual notification message', 'src/hooks.ts', 'const notify: HookCallback', 'Build a Slack-format text payload from the real Notification message. The classroom target is the per-run local receiver; no external Slack delivery is claimed.', 2, 4, 10), ('Set a one-second pre-tool hook timeout', 'src/hooks.ts', 'matcher: "Read",', 'Set timeout on the PreToolUse matcher and honour the supplied signal. Compare the observed blocked read with the post-tool case where the original tool result is retained.', 1, 3, 5), ('Record actual receiver status and cancellation', 'src/collector.ts', 'receipt.respondedAt =', 'Record a response only when it is actually sent. A cancelled request has no fabricated success status; its close event records the aborted connection.', 4, 1, 10), ('Drain tracked work and inspect evidence', 'src/agent.ts', 'await Promise.allSettled(background);', 'Wait for tracked reporting work before collecting final receipts and the unchanged fixture. Actual timestamps establish callback return, SDK progress and background completion order.', 3, 1, 8)]
document('/','Hooks. <em>Connect and diagnose.</em>','Deliver real local webhooks and inspect notifications, async work and timeouts.','<div class="flow"><div><b>01 · Observe</b><p>Receive actual SDK events</p></div><span>→</span><div><b>02 · Connect</b><p>Deliver real local HTTP requests</p></div><span>→</span><div><b>03 · Diagnose</b><p>Inspect receipts, errors and timing</p></div></div><section class="panel" id="controls"><h2>Explore practical hook integrations</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Practical hook experiment</label><select id="mode"><option value="audit-success">Audit webhook · successful local delivery</option><option value="audit-error">HTTP 503 · caught reporting error</option><option value="audit-abort">Request deadline · actual HTTP cancellation</option><option value="async-audit">Async logging · return before acknowledgement</option><option value="notification">Notification · review, forward locally, approve</option><option value="timeout-pre">PreToolUse timeout · read blocked</option><option value="timeout-post">PostToolUse timeout · result retained</option><option value="matcher-miss">Wrong matcher · file name misses Read</option><option value="matcher-fixed">Correct matcher · Read triggers delivery</option></select><label for="prediction">Predict the actual tool outcome</label><select id="prediction"><option value="execute">Execute · Read completes</option><option value="block">Block · Read is denied</option><option value="mixed">Mixed · inspect native results</option><option value="observe">Observe · inspect actual behavior</option></select><button id="run" class="primary" disabled>Run practical hook experiment →</button><p class="meta">Every example uses the real SDK and a disposable read-only fixture. HTTP delivery is real and local. Slack-format payloads do not go to an external workspace. In Notification, wait for the actual event before approving.</p></section><section class="step" id="review-panel" hidden><h2>Review the fixed classroom Read</h2><pre class="json-view"><code id="review-input" class="language-json">{}</code></pre><p id="review-status" class="note" aria-live="polite">Waiting for your decision.</p><div class="actions"><button id="approve-review" class="primary">Approve classroom Read</button><button id="deny-review">Deny classroom Read</button></div><p>Leave this pending for about nine seconds to observe the actual permission notification. Then approve or deny explicitly. Timeout and abort deny the request.</p></section><section class="step" id="delivery-panel"><h2>Real HTTP delivery timeline</h2><label for="delivery-select">Inspect an actual integration event</label><select id="delivery-select"><option>No events yet</option></select><pre class="json-view"><code id="delivery-record" class="language-json">{}</code></pre><details><summary>Full observed integration trace</summary><pre class="json-view"><code id="delivery-trace" class="language-json">[]</code></pre></details><div class="table"><table><thead><tr><th>#</th><th>Elapsed ms</th><th>Observed event</th><th>Channel</th></tr></thead><tbody id="delivery-history"></tbody></table></div><p>Slack is a local Slack-format receiver channel. Rows contain actual delivery and SDK event timestamps, not invented timing estimates.</p></section><section class="step" id="hook-panel"><h2>Actual hook callbacks</h2><label for="hook-select">Inspect an observed callback</label><select id="hook-select"><option>No callbacks yet</option></select><pre class="json-view"><code id="hook-output" class="language-json">{}</code></pre><div class="table"><table><thead><tr><th>#</th><th>Event</th><th>Callback</th><th>Tool</th><th>toolUseID</th></tr></thead><tbody id="hook-history"></tbody></table></div><p>Select an actual callback to inspect its input, returned output and AbortSignal state. Completion order is not a guaranteed policy sequence.</p></section><div class="workspace"><section class="panel" id="outcome"><h2 id="status" aria-live="polite">Ready</h2><p>Latest SDK-reported cost: <strong id="cost">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Compare the requested permissionMode with the SDK-reported mode. Compare registered hooks with the actual observed callbacks.</p></section></div><section class="step" id="pipeline-panel"><h2>Six hook behaviors</h2><p>Compare actual callback outputs with native tool results.</p><div class="grid"><article class="card"><h3>Post</h3><p>Send actual tool metadata as bounded JSON.</p></article><article class="card"><h3>Check</h3><p>Treat non-success HTTP statuses as delivery errors.</p></article><article class="card"><h3>Catch</h3><p>Preserve the tool result when reporting fails.</p></article><article class="card"><h3>Cancel</h3><p>Pass the hook signal and request deadline to fetch.</p></article><article class="card"><h3>Async</h3><p>Track background work and observe actual overlap.</p></article><article class="card"><h3>Diagnose</h3><p>Compare events, matchers, receipts and timeouts.</p></article></div></section><section class="step" id="configuration-panel"><h2>Actual hook configuration</h2><label for="configuration-file">Configuration projection</label><select id="configuration-file"></select><pre class="json-view"><code id="configuration-content" class="language-json">{}</code></pre><p>Inspect registered events and tool-name matchers. Empty output leaves normal permission checks in place.</p></section><section class="step" id="discovery-panel"><h2>Actual SDK initialization</h2><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre><p>This is the SDK initialization payload. A requested mode and a reported mode are separate evidence.</p></section><section class="step" id="trace-panel"><h2>Actual hooks, callback calls and turns</h2><pre class="json-view"><code id="trace" class="language-json">{}</code></pre><p>Actual callback records include event, input, output and tool-use IDs. Matching hooks can run in parallel.</p></section><section class="step" id="native-panel"><h2>Actual native tool feedback</h2><pre class="json-view"><code id="native" class="language-json">{}</code></pre><p>A denied Write can coexist with a successful final explanation. Inspect the actual attempt, callback decision and native feedback.</p></section><section class="step" id="evidence-panel"><h2>Hooks, session and independent file evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><p>Inspect actual hooks, native errors, callback counts, HTTP receipts, notification payloads, timing and independent file checks.</p></section><section class="step" id="comparison-panel"><h2>Compare this browser’s hook experiments</h2><p id="verdict">Predict execute, block, mixed or observe before running. Inspect actual hook output and independent results.</p><div class="table"><table><thead><tr><th>Experiment</th><th>Reference behavior</th><th>Prediction</th><th>Observed</th><th>Callbacks</th><th>Hooks</th><th>HTTP requests received</th></tr></thead><tbody id="history"></tbody></table></div><button id="download">Download redacted observations</button></section><section class="step" id="event-panel"><h2>Actual SDK messages</h2><ul id="events"></ul></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand practical webhook delivery, notifications and hook troubleshooting.',cards(learn))
